package org.brightstats.stats;

import java.nio.file.*;
import java.util.*;
import com.google.gson.*;

public final class MultiGroupSemChecks {
    private static int checks;
    private static void check(boolean value){checks++;if(!value)throw new AssertionError("Joint SEM check "+checks);}
    private static void close(double a,double b,double tolerance,String label){checks++;if(Double.isNaN(a)&&Double.isNaN(b))return;if(!Double.isFinite(a)||!Double.isFinite(b)||Math.abs(a-b)>tolerance*Math.max(1,Math.abs(b)))throw new AssertionError(label+": "+a+" != "+b);}
    private static void reject(Runnable action){try{action.run();throw new AssertionError("Invalid joint SEM accepted");}catch(IllegalArgumentException expected){checks++;}}
    private static SemModel.Model saturated(int p,boolean mean){List<String> names=java.util.stream.IntStream.range(0,p).mapToObj(j->"Y"+(j+1)).toList();List<SemModel.Parameter> parameters=new ArrayList<>();for(int i=0;i<p;i++)for(int j=0;j<=i;j++)parameters.add(new SemModel.Parameter("S"+i+j,List.of(new SemModel.Location(SemModel.Kind.COVARIANCE,i,j)),i==j?3:0,1));if(mean)for(int i=0;i<p;i++)parameters.add(new SemModel.Parameter("M"+i,List.of(new SemModel.Location(SemModel.Kind.INTERCEPT,i,0)),0,1));return new SemModel.Model(names,java.util.stream.IntStream.range(0,p).toArray(),new double[p][p],new double[p][p],new double[p],parameters);}
    public static void main(String[] args)throws Exception{
        Gson gson=new GsonBuilder().serializeSpecialFloatingPointValues().setPrettyPrinting().create();JsonArray cases=new JsonArray();
        for(int p=1;p<=2;p++)for(int shared=0;shared<3;shared++)for(var information:CovarianceSem.Information.values()){
            var model=saturated(p,true);Map<String,String> bindings=new LinkedHashMap<>();for(var parameter:model.parameters())if(shared==1&&parameter.name().startsWith("S")||shared==2)bindings.put(parameter.name(),parameter.name());double[][] sa=p==1?new double[][]{{2}}:new double[][]{{2,.4},{.4,1.5}},sb=p==1?new double[][]{{8}}:new double[][]{{8,-.6},{-.6,2.5}};double[] ma=p==1?new double[]{-1}:new double[]{-1,.4},mb=p==1?new double[]{2}:new double[]{2,-.7};var groups=List.of(new MultiGroupSem.Group("A",80,sa,ma,model,bindings),new MultiGroupSem.Group("B",120,sb,mb,model,bindings));var options=new CovarianceSem.Options(3000,1e-10,1e-14,CovarianceSem.Likelihood.NORMAL,true,.95,information);var work=new MultiGroupSem.Work(groups,options);var evaluation=work.evaluate(work.initial);for(int j=0;j<work.initial.length;j++){double[] high=work.initial.clone(),low=work.initial.clone();high[j]+=1e-6;low[j]-=1e-6;close(evaluation.gradient()[j],(work.evaluate(high).value()-work.evaluate(low).value())/2e-6,2e-8,"Joint gradient");}
            var fit=MultiGroupSem.fit(groups,options);check(fit.converged());check(fit.identified());check(fit.proper());check(fit.informationRank()==fit.freeParameters());check(fit.observations()==200);check(fit.degreesOfFreedom()==fit.moments()-fit.freeParameters());
            double[] pooledMean=new double[p];double[][] pooledCov=new double[p][p];for(int i=0;i<p;i++){pooledMean[i]=.4*ma[i]+.6*mb[i];for(int j=0;j<p;j++)pooledCov[i][j]=.4*sa[i][j]+.6*sb[i][j];}if(shared==2)for(int i=0;i<p;i++)for(int j=0;j<p;j++)pooledCov[i][j]+=.4*(ma[i]-pooledMean[i])*(ma[j]-pooledMean[j])+.6*(mb[i]-pooledMean[i])*(mb[j]-pooledMean[j]);
            for(int g=0;g<2;g++){double[] expectedMean=shared==2?pooledMean:g==0?ma:mb;double[][] expectedCov=shared==0?g==0?sa:sb:pooledCov;var group=fit.groups().get(g);for(int i=0;i<p;i++){close(group.impliedMeans()[i],expectedMean[i],2e-6,"Known Gaussian mean");for(int j=0;j<p;j++)close(group.impliedCovariance()[i][j],expectedCov[i][j],2e-6,"Known Gaussian covariance");}}
            if(p==1&&shared>0){int variance=fit.groups().get(0).globalParameters()[0];close(fit.parameterCovariance()[variance][variance],2*Math.pow(pooledCov[0][0],2)/200,2e-5,"Shared-variance sampling variance");if(shared==2){int mean=fit.groups().get(0).globalParameters()[1];close(fit.parameterCovariance()[mean][mean],pooledCov[0][0]/200,2e-5,"Shared-mean sampling variance");}else{int a=fit.groups().get(0).globalParameters()[1],b=fit.groups().get(1).globalParameters()[1];close(fit.parameterCovariance()[a][a],pooledCov[0][0]/80,2e-5,"Group A mean variance");close(fit.parameterCovariance()[b][b],pooledCov[0][0]/120,2e-5,"Group B mean variance");}}
            var contrasts=MultiGroupSem.contrasts(fit,"A");check(contrasts.size()==model.parameters().size());for(var test:contrasts)if(test.constrainedEqual()){close(test.difference(),0,0,"Fixed equality contrast");check(Double.isNaN(test.pValue()));}else check(Double.isFinite(test.standardError()));
            JsonObject value=new JsonObject();value.addProperty("kind","saturated");value.addProperty("shared",shared);value.add("groups",gson.toJsonTree(groups));value.add("options",gson.toJsonTree(options));value.add("result",gson.toJsonTree(fit));value.add("contrasts",gson.toJsonTree(contrasts));value.add("meanContrasts",gson.toJsonTree(MultiGroupSem.meanContrasts(fit,"A")));cases.add(value);
        }
        for(var likelihood:CovarianceSem.Likelihood.values()){
            var model3=saturated(1,true);var options3=new CovarianceSem.Options(3000,1e-10,1e-14,likelihood,true,.95,CovarianceSem.Information.EXPECTED);var groups3=List.of(new MultiGroupSem.Group("A",80,new double[][]{{2}},new double[]{-1},model3,Map.of("S00","variance","M0","mean")),new MultiGroupSem.Group("B",120,new double[][]{{8}},new double[]{2},model3,Map.of("S00","variance","M0","mean")),new MultiGroupSem.Group("C",70,new double[][]{{3}},new double[]{.7},model3,Map.of("S00","variance","M0","mean")));var fit3=MultiGroupSem.fit(groups3,options3);check(fit3.converged()&&fit3.identified()&&fit3.proper());check(fit3.groups().size()==3&&fit3.freeParameters()==2&&fit3.degreesOfFreedom()==4);JsonObject test3=new JsonObject();test3.addProperty("kind","three-group likelihood");test3.add("groups",gson.toJsonTree(groups3));test3.add("options",gson.toJsonTree(options3));test3.add("result",gson.toJsonTree(fit3));test3.add("contrasts",gson.toJsonTree(MultiGroupSem.contrasts(fit3,"A")));test3.add("meanContrasts",gson.toJsonTree(MultiGroupSem.meanContrasts(fit3,"A")));cases.add(test3);
        }
        var model=saturated(2,true);var options=new CovarianceSem.Options(3000,1e-10,1e-14,CovarianceSem.Likelihood.NORMAL,true,.95,CovarianceSem.Information.OBSERVED);var selected=List.of(new MultiGroupSem.Group("A",80,new double[][]{{2,.4},{.4,1.5}},new double[]{-1,.4},model,Map.of("S00","shared variance")),new MultiGroupSem.Group("B",120,new double[][]{{8,-.6},{-.6,2.5}},new double[]{2,-.7},model,Map.of("S00","shared variance")));var partial=MultiGroupSem.fit(selected,options);check(partial.converged()&&partial.identified());close(partial.groups().get(0).impliedCovariance()[0][0],5.6,2e-6,"Shared X variance");close(partial.groups().get(0).impliedCovariance()[0][1],1.12,2e-6,"Profiled group A covariance");close(partial.groups().get(0).impliedCovariance()[1][1],1.644,2e-6,"Profiled group A variance");close(partial.groups().get(1).impliedCovariance()[0][1],-.42,2e-6,"Profiled group B covariance");close(partial.groups().get(1).impliedCovariance()[1][1],2.4865,2e-6,"Profiled group B variance");JsonObject value=new JsonObject();value.addProperty("kind","partial variance");value.add("groups",gson.toJsonTree(selected));value.add("options",gson.toJsonTree(options));value.add("result",gson.toJsonTree(partial));value.add("contrasts",gson.toJsonTree(MultiGroupSem.contrasts(partial,"A")));value.add("meanContrasts",gson.toJsonTree(MultiGroupSem.meanContrasts(partial,"A")));cases.add(value);
        var unrestricted=MultiGroupSem.fit(selected.stream().map(g->new MultiGroupSem.Group(g.name(),g.observations(),g.covariance(),g.means(),g.model(),Map.of())).toList(),options);var comparison=MultiGroupSemComparison.compare(partial,unrestricted);check(comparison.differenceDf()==1);check(comparison.pValue()>=0&&comparison.pValue()<=1);reject(()->MultiGroupSemComparison.compare(unrestricted,partial));
        var one=List.of(selected.get(0));var single=MultiGroupSem.fit(one,options);var original=CovarianceSem.fitCovariance(one.get(0).covariance(),one.get(0).means(),80,model,options);close(single.logLikelihood(),original.logLikelihood(),2e-8,"Single-group reduction LL");for(int i=0;i<model.parameters().size();i++)close(single.estimates()[i],original.estimates()[i],2e-7,"Single-group reduction parameters");
        var provisional=MultiGroupSem.fit(selected,new CovarianceSem.Options(1,1e-12,1e-14,CovarianceSem.Likelihood.NORMAL,true,.95,CovarianceSem.Information.EXPECTED));check(!provisional.converged());check(Double.isNaN(provisional.chiSquarePValue()));check(provisional.terms().stream().allMatch(t->Double.isNaN(t.standardError())));
        var unused=new SemModel.Model(List.of("Y","F"),new int[]{0},new double[2][2],new double[][]{{1,0},{0,0}},new double[2],List.of(new SemModel.Parameter("Unused",List.of(new SemModel.Location(SemModel.Kind.COVARIANCE,1,1)),1,1)));var unidentified=MultiGroupSem.fit(List.of(new MultiGroupSem.Group("A",50,new double[][]{{1}},new double[]{0},unused,Map.of())),CovarianceSem.Options.defaults());check(!unidentified.identified()&&unidentified.informationRank()==0&&!unidentified.diagnostics().informationPositiveDefinite());
        reject(()->MultiGroupSem.fit(List.of(new MultiGroupSem.Group("A",50,new double[][]{{1,1},{1,1}},new double[]{0,0},model,Map.of())),options));reject(()->MultiGroupSem.fit(List.of(new MultiGroupSem.Group("A",50,new double[][]{{1,0},{0,1}},new double[]{0,0},model,Map.of("unknown","tag"))),options));reject(()->MultiGroupSem.fit(List.of(selected.get(0),selected.get(0)),options));
        Thread.currentThread().interrupt();try{MultiGroupSem.fit(selected,options);throw new AssertionError("Joint SEM ignored cancellation");}catch(java.util.concurrent.CancellationException expected){checks++;}finally{Thread.interrupted();}
        Random random=new Random(20261109);for(int variant=0;variant<3;variant++){
            int na=250,nb=300;double[][] a=new double[na][3],b=new double[nb][3],pooled=new double[na+nb][3];for(int group=0;group<2;group++){double[][] rows=group==0?a:b;for(int i=0;i<rows.length;i++){double factor=(group==0?1:1.2)*random.nextGaussian()+(group==0?0:.6);for(int j=0;j<3;j++)rows[i][j]=new double[]{1,2,-1}[j]+new double[]{1,.8,.7}[j]*factor+((variant==2&&group==1)?1:.6)*random.nextGaussian()+((variant==1&&group==1&&j==1)?.5:0);pooled[(group==0?0:na)+i]=rows[i].clone();}}
            var template=SemModel.reflective(List.of("Y1","Y2","Y3"),pooled,List.of(new PlsSem.Block("F",new int[]{0,1,2},PlsSem.Mode.A)),List.of(),true,true);var samples=List.of(SemInvariance.Sample.fromData("A",a,options),SemInvariance.Sample.fromData("B",b,options));
            if(variant==0){var base=template.model();double[][] directed=base.directed();directed[0][1]=.1;var invalid=new SemModel.Prepared(new SemModel.Model(base.variables(),base.observed(),directed,base.covariance(),base.intercepts(),base.parameters()),template.columns(),template.factors());reject(()->SemInvariance.fitStage(invalid,samples,SemInvariance.Stage.CONFIGURAL,options));}
            for(boolean strict:new boolean[]{false,true}){var sequence=SemInvariance.sequence(template,samples,options,strict,null);check(sequence.steps().size()==(strict?5:4));int[] dfs=strict?new int[]{0,2,4,7,8}:new int[]{0,2,4,5};MultiGroupSem.Fit previous=null;for(int index=0;index<sequence.steps().size();index++){var step=sequence.steps().get(index);if(step.fit()==null)throw new AssertionError("Invariance stage failed: "+step.failure());var fit=step.fit();check(fit.converged()&&fit.identified()&&fit.proper());check(fit.degreesOfFreedom()==dfs[index]);if(index>0){if(step.previousComparison()==null)throw new AssertionError("Invariance comparison failed: "+step.comparisonUnavailable());check(step.previousComparison().differenceDf()==dfs[index]-dfs[index-1]);check(step.previousComparison().difference()>=0);}if(index==1)check(MultiGroupSemComparison.compare(fit,previous).differenceDf()==2);
                    JsonObject test=new JsonObject();test.addProperty("kind","invariance");test.addProperty("variant",variant);test.addProperty("stage",step.stage().name());test.addProperty("strict",strict);test.add("groups",gson.toJsonTree(fit.groups().stream().map(MultiGroupSem.GroupFit::input).toList()));test.add("options",gson.toJsonTree(options));test.add("result",gson.toJsonTree(fit));test.add("contrasts",gson.toJsonTree(MultiGroupSem.contrasts(fit,"A")));test.add("meanContrasts",gson.toJsonTree(MultiGroupSem.meanContrasts(fit,"A")));cases.add(test);previous=fit;
                }}
        }
        Path output=Path.of(args[0]);Files.createDirectories(output);Files.writeString(output.resolve("cases.json"),gson.toJson(cases));System.out.println("{\"joint_sem_cases\":"+cases.size()+",\"checks\":"+checks+"}");
    }
}
